// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address actor, address recipient) public {
        vm.assume(recipient != address(c));
        vm.assume(recipient != address(0));

        // fund the contract exactly with the 100-wei bonus it will pay out
        vm.deal(address(c), 100);

        vm.prank(actor);
        c.getFirstWithdrawalBonus(recipient);

        // General rule: a completed getFirstWithdrawalBonus always pays out the
        // accumulated 100-wei reward, draining the contract's balance.
        assertTrue(address(c).balance == 0);
    }
}
